const AppIcon = ({
  source,
  size = 22,
  containerSize = 38,
  variant = 'neutral',
  shape = 'rounded',
  tintColor,
  style,
  imageStyle,
  accessibilityLabel,
  themeMode,
  iconKey,
  opticalScale,
  translateY,
}) => {
  const ctx = React.useContext(ThemeContext);
  const resolvedMode = themeMode || (ctx && ctx.mode) || 'light';
  const theme = themeService.getIconTheme(variant, resolvedMode);
  const resolvedTint = tintColor !== undefined ? tintColor : theme.tint;

  const metrics = iconMetricsService.getIconMetrics(iconKey || (typeof source === 'string' ? source : ''));
  const effectiveScale = opticalScale !== undefined ? opticalScale : metrics.opticalScale;
  const effectiveTranslateY = translateY !== undefined ? translateY : metrics.translateY;
  const effectiveWidth = Math.round(size * effectiveScale);
  const effectiveHeight = Math.round(size * effectiveScale);
  const transformStyle = effectiveTranslateY ? [{ translateY: effectiveTranslateY }] : undefined;

  if (shape === 'none') {
    return (
      <Image
        source={source}
        style={[
          { width: effectiveWidth, height: effectiveHeight },
          transformStyle ? { transform: transformStyle } : {},
          resolvedTint ? { tintColor: resolvedTint } : {},
          imageStyle,
        ]}
        resizeMode="contain"
        accessibilityLabel={accessibilityLabel}
      />
    );
  }

  const isCircle = shape === 'circle';
  const radius = isCircle ? containerSize / 2 : (shape === 'rounded' ? Math.round(containerSize * 0.28) : 10);

  return (
    <View
      style={[
        {
          width: containerSize,
          height: containerSize,
          borderRadius: radius,
          backgroundColor: theme.bg,
          borderTopWidth: 1.5,
          borderTopColor: theme.borderTop,
          borderBottomWidth: 3,
          borderBottomColor: theme.borderBottom,
          borderLeftWidth: 1,
          borderRightWidth: 1,
          borderColor: theme.borderSides,
          justifyContent: 'center',
          alignItems: 'center',
          elevation: resolvedMode === 'dark' ? 4 : 3,
          shadowColor: resolvedMode === 'dark' ? '#000000' : (theme.shadowColor || '#000000'),
          shadowOffset: { width: 0, height: resolvedMode === 'dark' ? 3 : 2 },
          shadowOpacity: resolvedMode === 'dark' ? 0.35 : 0.12,
          shadowRadius: resolvedMode === 'dark' ? 4 : 3.5,
          overflow: 'hidden',
          position: 'relative',
        },
        style,
      ]}
      accessibilityLabel={accessibilityLabel}
    >
      {/* Specular 3D dimensional highlight across the top curved bevel */}
      <View
        pointerEvents="none"
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: Math.round(containerSize * 0.36),
          borderTopLeftRadius: radius,
          borderTopRightRadius: radius,
          backgroundColor: resolvedMode === 'dark' ? 'rgba(255, 255, 255, 0.04)' : 'rgba(255, 255, 255, 0.32)',
        }}
      />
      <Image
        source={source}
        style={[
          { width: effectiveWidth, height: effectiveHeight },
          transformStyle ? { transform: transformStyle } : {},
          resolvedTint ? { tintColor: resolvedTint } : {},
          imageStyle,
        ]}
        resizeMode="contain"
      />
    </View>
  );
};

const TwoToneDivider = ({ style, marginVertical = 6 }) => {
  const ctx = React.useContext(ThemeContext);
  const isDark = ctx && ctx.mode === 'dark';
  return (
    <View style={[{ width: '100%', marginVertical }, style]}>
      <View style={{ height: 1, backgroundColor: isDark ? '#334155' : '#E2E8F0' }} />
      <View style={{ height: 1, backgroundColor: isDark ? '#1E293B' : '#FFFFFF' }} />
    </View>
  );
};

const TwoToneVerticalDivider = ({ height = 32, style }) => {
  const ctx = React.useContext(ThemeContext);
  const isDark = ctx && ctx.mode === 'dark';
  return (
    <View style={[{ flexDirection: 'row', height, alignItems: 'center' }, style]}>
      <View style={{ width: 1, height: '100%', backgroundColor: isDark ? '#334155' : '#E2E8F0' }} />
      <View style={{ width: 1, height: '100%', backgroundColor: isDark ? '#1E293B' : '#FFFFFF' }} />
    </View>
  );
};

const SectionHeader = ({ title, count, badge, actionText, onAction, style }) => {
  const ctx = React.useContext(ThemeContext);
  const isDark = ctx && ctx.mode === 'dark';
  const theme = ctx ? ctx.theme : themeService.LIGHT_THEME;
  return (
    <View style={[styles.sectionHeaderRow, style]}>
      <View style={styles.sectionHeaderLeft}>
        <View style={styles.sectionHeaderAccentPill} />
        <Text style={[styles.sectionHeaderTitle, isDark && { color: theme.textPrimary }]}>{title}</Text>
        {count !== undefined && (
          <View style={[styles.sectionHeaderCountBadge, isDark && { backgroundColor: theme.cardBorder }]}>
            <Text style={[styles.sectionHeaderCountText, isDark && { color: theme.textSecondary }]}>{count}</Text>
          </View>
        )}
        {badge && (
          <View style={styles.sectionHeaderBadge}>
            <Text style={styles.sectionHeaderBadgeText}>{badge}</Text>
          </View>
        )}
      </View>
      {actionText && (
        <TouchableOpacity onPress={onAction} hitSlop={{ top: 8, bottom: 8, left: 8, right: 8 }} activeOpacity={0.7}>
          <View style={{ flexDirection: 'row', alignItems: 'center' }}>
            <Text style={[styles.sectionHeaderAction, isDark && { color: theme.primary }]}>{actionText}</Text>
            <Image
              source={require('./assets/icons/arrow_right.png')}
              style={{ width: 11, height: 11, tintColor: isDark ? theme.primary : COLORS.primary, marginLeft: 3 }}
              resizeMode="contain"
            />
          </View>
        </TouchableOpacity>
      )}
    </View>
  );
};

export { Card3D, Button3D, SquircleBadge, TwoToneDivider, TwoToneVerticalDivider, SectionHeader };

