                <Text style={{ fontSize: 12, fontWeight: 'bold', color: isDark ? currentTheme.textPrimary : '#1E293B' }}>
                  {rechargeVoucherData?.mobileNumber} ({rechargeVoucherData?.operator})
                </Text>
