                      await persistData({ tallyMessageBalance: newBal });
                      Alert.alert(tStatic("অভিনন্দন!"), `${toBengaliNumber(pkg.count)}${tStatic(" টি এসএমএস সফলভাবে আপনার অ্যাকাউন্টে যোগ হয়েছে।")}`);
